package library.management;

import library.management.entities.Book;
import library.management.entities.Member;
import library.management.service.BookServices;
import library.management.service.MemberServices;

import java.io.IOException;
import java.util.List;
import java.util.Scanner;

public class App {

    public static void main(String[] args) {

        System.out.println("Running Library Management System");

        Scanner scanner = new Scanner(System.in);

        BookServices bookService;
        MemberServices memberService;

        try {
            bookService = new BookServices();
            memberService = new MemberServices();
        } catch (IOException e) {
            e.printStackTrace();
            return;
        }

        int option = 0;

        while(option != 6) {

            System.out.println("\nChoose Option");
            System.out.println("1. Add Book");
            System.out.println("2. View All Books");
            System.out.println("3. Search Book");
            System.out.println("4. Add Member");
            System.out.println("5. View Members");
            System.out.println("6. Exit");

            option = scanner.nextInt();
            scanner.nextLine();

            switch(option) {

                case 1:

                    System.out.println("Enter Book Id");
                    String bookId = scanner.nextLine();

                    System.out.println("Enter Book Title");
                    String title = scanner.nextLine();

                    System.out.println("Enter Author");
                    String author = scanner.nextLine();

                    System.out.println("Enter Category");
                    String category = scanner.nextLine();

                    System.out.println("Enter Quantity");
                    Integer quantity = scanner.nextInt();
                    scanner.nextLine();

                    Book book = new Book(
                            bookId,
                            title,
                            author,
                            category,
                            quantity
                    );

                    bookService.addBook(book);

                    System.out.println("Book Added Successfully");

                    break;

                case 2:

                    List<Book> books =
                            bookService.getAllBooks();

                    books.forEach(b ->
                            System.out.println(
                                    b.getBookInfo()
                            ));

                    break;

                case 3:

                    System.out.println("Enter Book Title");

                    String searchTitle =
                            scanner.nextLine();

                    List<Book> searchedBooks =
                            bookService.searchBookByTitle(searchTitle);

                    searchedBooks.forEach(b ->
                            System.out.println(
                                    b.getBookInfo()
                            ));

                    break;

                case 4:

                    System.out.println("Enter Member Id");
                    String memberId = scanner.nextLine();

                    System.out.println("Enter Member Name");
                    String memberName = scanner.nextLine();

                    System.out.println("Enter Email");
                    String email = scanner.nextLine();

                    System.out.println("Enter Phone");
                    String phone = scanner.nextLine();

                    System.out.println("Enter Membership Date");
                    String date = scanner.nextLine();

                    Member member = new Member(
                            memberId,
                            memberName,
                            email,
                            phone,
                            date
                    );

                    memberService.addMember(member);

                    System.out.println("Member Added Successfully");

                    break;

                case 5:

                    List<Member> members =
                            memberService.getAllMembers();

                    members.forEach(m ->
                            System.out.println(
                                    m.getMemberInfo()
                            ));

                    break;

                case 6:

                    System.out.println("Exiting...");
                    break;

                default:

                    System.out.println("Invalid Option");
            }
        }
    }
}